//! HTTP routes and handlers.

use std::sync::Arc;

use axum::body::Bytes;
use axum::extract::{DefaultBodyLimit, Path, RawQuery, State};
use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Json, Router};
use serde_json::json;

use crate::db::Store;
use crate::model::{ListQuery, Note, NoteInput, ValidationError};

const MAX_BODY_BYTES: usize = 64 * 1024 * 1024;

type AppState = Arc<Store>;

/// Errors a handler can return, mapped to HTTP responses with JSON bodies.
#[derive(Debug)]
pub enum ApiError {
    BadRequest(String),
    NotFound,
    MethodNotAllowed,
    Internal(String),
}

impl From<ValidationError> for ApiError {
    fn from(e: ValidationError) -> Self {
        Self::BadRequest(e.0)
    }
}

impl From<rusqlite::Error> for ApiError {
    fn from(e: rusqlite::Error) -> Self {
        Self::Internal(e.to_string())
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, message) = match self {
            Self::BadRequest(msg) => (StatusCode::BAD_REQUEST, msg),
            Self::NotFound => (StatusCode::NOT_FOUND, "not found".to_owned()),
            Self::MethodNotAllowed => {
                (StatusCode::METHOD_NOT_ALLOWED, "method not allowed".to_owned())
            }
            Self::Internal(msg) => {
                eprintln!("internal error: {msg}");
                (StatusCode::INTERNAL_SERVER_ERROR, "internal error".to_owned())
            }
        };
        (status, Json(json!({ "error": message }))).into_response()
    }
}

type ApiResult<T> = Result<T, ApiError>;

pub fn router(store: Arc<Store>) -> Router {
    Router::new()
        .route("/health", get(health))
        .route("/notes", get(list_notes).post(create_note))
        .route("/notes/{id}", get(get_note).put(update_note).delete(delete_note))
        .route("/stats", get(stats))
        .route("/tags", get(tags))
        .fallback(|| async { ApiError::NotFound })
        .method_not_allowed_fallback(|| async { ApiError::MethodNotAllowed })
        .layer(DefaultBodyLimit::max(MAX_BODY_BYTES))
        .with_state(store)
}

/// Runs a database operation on the blocking thread pool.
async fn run_db<T, F>(store: AppState, f: F) -> ApiResult<T>
where
    F: FnOnce(&Store) -> Result<T, ApiError> + Send + 'static,
    T: Send + 'static,
{
    tokio::task::spawn_blocking(move || f(&store))
        .await
        .map_err(|e| ApiError::Internal(e.to_string()))?
}

/// Note ids in paths must be positive integers; anything else is an unknown note.
fn parse_id(raw: &str) -> ApiResult<i64> {
    match raw.parse::<i64>() {
        Ok(id) if id > 0 && raw.bytes().all(|b| b.is_ascii_digit()) => Ok(id),
        _ => Err(ApiError::NotFound),
    }
}

async fn health() -> &'static str {
    "ok"
}

async fn create_note(State(store): State<AppState>, body: Bytes) -> ApiResult<impl IntoResponse> {
    let input = NoteInput::from_json(&body)?;
    let note = run_db(store, move |s| Ok(s.create(input)?)).await?;
    Ok((StatusCode::CREATED, Json(note)))
}

async fn get_note(State(store): State<AppState>, Path(id): Path<String>) -> ApiResult<Json<Note>> {
    let id = parse_id(&id)?;
    run_db(store, move |s| s.get(id)?.ok_or(ApiError::NotFound)).await.map(Json)
}

async fn update_note(
    State(store): State<AppState>,
    Path(id): Path<String>,
    body: Bytes,
) -> ApiResult<Json<Note>> {
    let id = parse_id(&id)?;
    let input = NoteInput::from_json(&body)?;
    run_db(store, move |s| s.update(id, input)?.ok_or(ApiError::NotFound)).await.map(Json)
}

async fn delete_note(State(store): State<AppState>, Path(id): Path<String>) -> ApiResult<StatusCode> {
    let id = parse_id(&id)?;
    run_db(store, move |s| match s.delete(id)? {
        true => Ok(StatusCode::NO_CONTENT),
        false => Err(ApiError::NotFound),
    })
    .await
}

async fn list_notes(
    State(store): State<AppState>,
    RawQuery(query): RawQuery,
) -> ApiResult<impl IntoResponse> {
    let query = ListQuery::from_query_string(query.as_deref().unwrap_or(""))?;
    let notes = run_db(store, move |s| Ok(s.list(&query)?)).await?;
    Ok(Json(json!({ "notes": notes })))
}

async fn stats(State(store): State<AppState>) -> ApiResult<impl IntoResponse> {
    let (count, tags) = run_db(store, |s| Ok(s.stats()?)).await?;
    Ok(Json(json!({ "notes": count, "tags": tags })))
}

async fn tags(State(store): State<AppState>) -> ApiResult<impl IntoResponse> {
    let counts = run_db(store, |s| Ok(s.tag_counts()?)).await?;
    let tags: Vec<_> = counts
        .into_iter()
        .map(|(tag, count)| json!({ "tag": tag, "count": count }))
        .collect();
    Ok(Json(json!({ "tags": tags })))
}

//! SQLite-backed persistence for notes.

use std::collections::BTreeMap;
use std::path::Path;
use std::sync::{Mutex, MutexGuard};

use rusqlite::{Connection, OptionalExtension, Transaction, params};

use crate::model::{ListQuery, Note, NoteInput};

const SCHEMA: &str = "
CREATE TABLE IF NOT EXISTS notes (
    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    body  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS note_tags (
    note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
    tag     TEXT NOT NULL,
    PRIMARY KEY (note_id, tag)
) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS note_tags_tag ON note_tags(tag, note_id);
";

/// Thread-safe handle to the notes database.
///
/// A single connection serialised by a mutex keeps writes consistent; callers
/// are expected to invoke these methods from a blocking-capable thread.
pub struct Store {
    conn: Mutex<Connection>,
}

impl Store {
    pub fn open(path: impl AsRef<Path>) -> rusqlite::Result<Self> {
        Self::init(Connection::open(path)?)
    }

    #[cfg(test)]
    pub fn open_in_memory() -> rusqlite::Result<Self> {
        Self::init(Connection::open_in_memory()?)
    }

    fn init(conn: Connection) -> rusqlite::Result<Self> {
        conn.pragma_update(None, "journal_mode", "WAL")?;
        conn.pragma_update(None, "synchronous", "NORMAL")?;
        conn.pragma_update(None, "foreign_keys", true)?;
        conn.busy_timeout(std::time::Duration::from_secs(5))?;
        conn.execute_batch(SCHEMA)?;
        Ok(Self { conn: Mutex::new(conn) })
    }

    fn conn(&self) -> MutexGuard<'_, Connection> {
        // A panic while holding the lock cannot leave SQLite in a torn state
        // (transactions roll back on drop), so recovering is safe.
        self.conn.lock().unwrap_or_else(|e| e.into_inner())
    }

    pub fn create(&self, input: NoteInput) -> rusqlite::Result<Note> {
        let mut conn = self.conn();
        let tx = conn.transaction()?;
        tx.execute(
            "INSERT INTO notes (title, body) VALUES (?1, ?2)",
            params![input.title, input.body],
        )?;
        let id = tx.last_insert_rowid();
        insert_tags(&tx, id, &input.tags)?;
        tx.commit()?;
        Ok(Note { id, title: input.title, body: input.body, tags: input.tags })
    }

    pub fn get(&self, id: i64) -> rusqlite::Result<Option<Note>> {
        let conn = self.conn();
        let row = conn
            .query_row("SELECT title, body FROM notes WHERE id = ?1", [id], |r| {
                Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?))
            })
            .optional()?;
        let Some((title, body)) = row else { return Ok(None) };
        let tags = conn
            .prepare_cached("SELECT tag FROM note_tags WHERE note_id = ?1 ORDER BY tag")?
            .query_map([id], |r| r.get(0))?
            .collect::<rusqlite::Result<Vec<String>>>()?;
        Ok(Some(Note { id, title, body, tags }))
    }

    /// Replaces a note's content; returns `None` if it does not exist.
    pub fn update(&self, id: i64, input: NoteInput) -> rusqlite::Result<Option<Note>> {
        let mut conn = self.conn();
        let tx = conn.transaction()?;
        let changed = tx.execute(
            "UPDATE notes SET title = ?1, body = ?2 WHERE id = ?3",
            params![input.title, input.body, id],
        )?;
        if changed == 0 {
            return Ok(None);
        }
        tx.execute("DELETE FROM note_tags WHERE note_id = ?1", [id])?;
        insert_tags(&tx, id, &input.tags)?;
        tx.commit()?;
        Ok(Some(Note { id, title: input.title, body: input.body, tags: input.tags }))
    }

    /// Deletes a note; returns whether it existed.
    pub fn delete(&self, id: i64) -> rusqlite::Result<bool> {
        let conn = self.conn();
        Ok(conn.execute("DELETE FROM notes WHERE id = ?1", [id])? > 0)
    }

    pub fn list(&self, query: &ListQuery) -> rusqlite::Result<Vec<Note>> {
        let conn = self.conn();
        let mut stmt = conn.prepare_cached(
            "SELECT n.id, n.title, n.body,
                    (SELECT group_concat(t.tag, ',') FROM note_tags t WHERE t.note_id = n.id)
             FROM notes n
             WHERE n.id > ?1
               AND (?2 IS NULL OR EXISTS
                    (SELECT 1 FROM note_tags t WHERE t.note_id = n.id AND t.tag = ?2))
               AND (?3 IS NULL OR instr(lower(n.title), lower(?3)) > 0
                               OR instr(lower(n.body), lower(?3)) > 0)
             ORDER BY n.id
             LIMIT ?4",
        )?;
        let rows = stmt.query_map(
            params![query.after.unwrap_or(i64::MIN), query.tag, query.q, query.limit],
            |r| {
                // Tags never contain commas, so the concatenation splits cleanly.
                let joined: Option<String> = r.get(3)?;
                let mut tags: Vec<String> = joined
                    .map(|s| s.split(',').map(str::to_owned).collect())
                    .unwrap_or_default();
                tags.sort_unstable();
                Ok(Note { id: r.get(0)?, title: r.get(1)?, body: r.get(2)?, tags })
            },
        )?;
        rows.collect()
    }

    /// Number of notes per tag, ordered by count descending, then tag ascending.
    pub fn tag_counts(&self) -> rusqlite::Result<Vec<(String, i64)>> {
        let conn = self.conn();
        let mut stmt = conn.prepare_cached(
            "SELECT tag, count(*) AS c FROM note_tags GROUP BY tag ORDER BY c DESC, tag ASC",
        )?;
        let rows = stmt.query_map([], |r| Ok((r.get(0)?, r.get(1)?)))?;
        rows.collect()
    }

    /// Note count and per-tag counts read in one consistent snapshot.
    pub fn stats(&self) -> rusqlite::Result<(i64, BTreeMap<String, i64>)> {
        let mut conn = self.conn();
        let tx = conn.transaction()?;
        let count = tx.query_row("SELECT count(*) FROM notes", [], |r| r.get(0))?;
        let tags = tx
            .prepare_cached("SELECT tag, count(*) FROM note_tags GROUP BY tag")?
            .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))?
            .collect::<rusqlite::Result<_>>()?;
        Ok((count, tags))
    }
}

fn insert_tags(tx: &Transaction<'_>, id: i64, tags: &[String]) -> rusqlite::Result<()> {
    let mut stmt = tx.prepare_cached("INSERT INTO note_tags (note_id, tag) VALUES (?1, ?2)")?;
    for tag in tags {
        stmt.execute(params![id, tag])?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn input(title: &str, body: &str, tags: &[&str]) -> NoteInput {
        NoteInput {
            title: title.into(),
            body: body.into(),
            tags: tags.iter().map(|s| s.to_string()).collect(),
        }
    }

    #[test]
    fn crud_and_ids_not_reused() {
        let s = Store::open_in_memory().unwrap();
        let a = s.create(input("a", "", &["x"])).unwrap();
        let b = s.create(input("b", "", &[])).unwrap();
        assert_eq!((a.id, b.id), (1, 2));
        assert!(s.delete(2).unwrap());
        assert!(!s.delete(2).unwrap());
        assert_eq!(s.create(input("c", "", &[])).unwrap().id, 3);
        let u = s.update(1, input("A", "body", &["y", "z"])).unwrap().unwrap();
        assert_eq!(s.get(1).unwrap().unwrap(), u);
        assert!(s.update(2, input("x", "", &[])).unwrap().is_none());
        assert!(s.get(2).unwrap().is_none());
    }

    #[test]
    fn list_filters_and_counts() {
        let s = Store::open_in_memory().unwrap();
        s.create(input("Hello", "", &["g"])).unwrap();
        s.create(input("other", "say HELLO 100%", &["g", "m"])).unwrap();
        s.create(input("none", "", &[])).unwrap();
        let ids = |q: ListQuery| s.list(&q).unwrap().iter().map(|n| n.id).collect::<Vec<_>>();
        assert_eq!(ids(ListQuery::default()), [1, 2, 3]);
        assert_eq!(ids(ListQuery { q: Some("hello".into()), ..Default::default() }), [1, 2]);
        assert_eq!(ids(ListQuery { q: Some("0%".into()), ..Default::default() }), [2]);
        assert_eq!(ids(ListQuery { tag: Some("m".into()), ..Default::default() }), [2]);
        assert_eq!(ids(ListQuery { after: Some(1), limit: 1, ..Default::default() }), [2]);
        assert_eq!(s.list(&ListQuery::default()).unwrap()[1].tags, ["g", "m"]);
        assert_eq!(s.tag_counts().unwrap(), [("g".into(), 2), ("m".into(), 1)]);
        s.delete(2).unwrap();
        let (count, tags) = s.stats().unwrap();
        assert_eq!(count, 2);
        assert_eq!(tags, BTreeMap::from([("g".into(), 1)]));
    }
}

//! `notes <port>`: a small JSON notes service backed by SQLite.

mod api;
mod db;
mod model;

use std::net::{Ipv4Addr, SocketAddr};
use std::sync::Arc;

use anyhow::{Context, Result};

#[tokio::main]
async fn main() -> Result<()> {
    let port: u16 = std::env::args()
        .nth(1)
        .context("usage: app <port>")?
        .parse()
        .context("port must be an integer from 0 to 65535")?;
    let db_path = std::env::var_os("NOTES_DB").context("NOTES_DB must be set")?;

    let store = db::Store::open(&db_path)
        .with_context(|| format!("opening database {}", db_path.to_string_lossy()))?;
    let app = api::router(Arc::new(store));

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .with_context(|| format!("binding {addr}"))?;
    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .context("server error")
}

/// Resolves on Ctrl-C or SIGTERM.
async fn shutdown_signal() {
    use tokio::signal::unix::{SignalKind, signal};
    let ctrl_c = async {
        let _ = tokio::signal::ctrl_c().await;
    };
    match signal(SignalKind::terminate()) {
        Ok(mut term) => tokio::select! {
            _ = ctrl_c => {}
            _ = term.recv() => {}
        },
        Err(_) => ctrl_c.await,
    }
}

//! Note data types and validation of client input.

use serde::Serialize;
use serde_json::{Map, Value};

pub const MAX_TITLE_CHARS: usize = 200;
pub const MAX_TAG_CHARS: usize = 32;
pub const MAX_LIMIT: i64 = 100;

/// A stored note as returned to clients.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Note {
    pub id: i64,
    pub title: String,
    pub body: String,
    pub tags: Vec<String>,
}

/// Validated content of a note, as accepted by create and update.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NoteInput {
    pub title: String,
    pub body: String,
    pub tags: Vec<String>,
}

/// Filters for listing notes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ListQuery {
    pub tag: Option<String>,
    pub q: Option<String>,
    pub after: Option<i64>,
    pub limit: i64,
}

impl Default for ListQuery {
    fn default() -> Self {
        Self { tag: None, q: None, after: None, limit: MAX_LIMIT }
    }
}

/// A client error with a human-readable message.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ValidationError(pub String);

impl std::fmt::Display for ValidationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for ValidationError {}

fn invalid(msg: impl Into<String>) -> ValidationError {
    ValidationError(msg.into())
}

pub fn is_valid_tag(tag: &str) -> bool {
    (1..=MAX_TAG_CHARS).contains(&tag.len())
        && tag.bytes().all(|b| matches!(b, b'a'..=b'z' | b'0'..=b'9' | b'-'))
}

impl NoteInput {
    /// Parses and validates a raw request body.
    pub fn from_json(raw: &[u8]) -> Result<Self, ValidationError> {
        let value: Value =
            serde_json::from_slice(raw).map_err(|e| invalid(format!("invalid JSON: {e}")))?;
        match value {
            Value::Object(map) => Self::from_object(&map),
            _ => Err(invalid("request body must be a JSON object")),
        }
    }

    fn from_object(map: &Map<String, Value>) -> Result<Self, ValidationError> {
        let title = match map.get("title") {
            None => return Err(invalid("title is required")),
            Some(Value::String(s)) => s.trim_matches(' ').to_owned(),
            Some(_) => return Err(invalid("title must be a string")),
        };
        let len = title.chars().count();
        if len == 0 || len > MAX_TITLE_CHARS {
            return Err(invalid(format!(
                "title must be 1-{MAX_TITLE_CHARS} characters"
            )));
        }

        let body = match map.get("body") {
            None => String::new(),
            Some(Value::String(s)) => s.clone(),
            Some(_) => return Err(invalid("body must be a string")),
        };

        let tags = match map.get("tags") {
            None => Vec::new(),
            Some(Value::Array(items)) => {
                let mut tags = items
                    .iter()
                    .map(|item| match item {
                        Value::String(s) if is_valid_tag(s) => Ok(s.clone()),
                        _ => Err(invalid(format!(
                            "each tag must be 1-{MAX_TAG_CHARS} characters from a-z, 0-9 and -"
                        ))),
                    })
                    .collect::<Result<Vec<_>, _>>()?;
                tags.sort_unstable();
                tags.dedup();
                tags
            }
            Some(_) => return Err(invalid("tags must be an array of strings")),
        };

        Ok(Self { title, body, tags })
    }
}

impl ListQuery {
    /// Parses a URL query string (without the leading `?`).
    pub fn from_query_string(query: &str) -> Result<Self, ValidationError> {
        let mut out = Self::default();
        for (key, value) in form_urlencoded::parse(query.as_bytes()) {
            match key.as_ref() {
                "tag" => out.tag = Some(value.into_owned()),
                "q" => out.q = Some(value.into_owned()),
                "after" => {
                    let after = value
                        .parse::<i64>()
                        .map_err(|_| invalid("after must be an integer"))?;
                    out.after = Some(after);
                }
                "limit" => {
                    out.limit = value
                        .parse::<i64>()
                        .ok()
                        .filter(|n| (1..=MAX_LIMIT).contains(n))
                        .ok_or_else(|| {
                            invalid(format!("limit must be an integer from 1 to {MAX_LIMIT}"))
                        })?;
                }
                _ => {}
            }
        }
        Ok(out)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(s: &str) -> Result<NoteInput, ValidationError> {
        NoteInput::from_json(s.as_bytes())
    }

    #[test]
    fn defaults_and_normalisation() {
        let n = parse(r#"{"title":"  hi  ","tags":["b","a","b"]}"#).unwrap();
        assert_eq!(n.title, "hi");
        assert_eq!(n.body, "");
        assert_eq!(n.tags, ["a", "b"]);
    }

    #[test]
    fn rejects_bad_input() {
        for body in [
            "",
            "{",
            "[]",
            "null",
            "{}",
            r#"{"title":5}"#,
            r#"{"title":"   "}"#,
            r#"{"title":"x","body":null}"#,
            r#"{"title":"x","body":3}"#,
            r#"{"title":"x","tags":"a"}"#,
            r#"{"title":"x","tags":[1]}"#,
            r#"{"title":"x","tags":[""]}"#,
            r#"{"title":"x","tags":["A"]}"#,
            r#"{"title":"x","tags":["a_b"]}"#,
        ] {
            assert!(parse(body).is_err(), "{body} should be rejected");
        }
    }

    #[test]
    fn title_length_counts_characters() {
        let ok = format!(r#"{{"title":"{}"}}"#, "é".repeat(200));
        assert!(parse(&ok).is_ok());
        let long = format!(r#"{{"title":"{}"}}"#, "a".repeat(201));
        assert!(parse(&long).is_err());
    }

    #[test]
    fn tag_length() {
        assert!(is_valid_tag(&"a".repeat(32)));
        assert!(!is_valid_tag(&"a".repeat(33)));
    }

    #[test]
    fn list_query() {
        let q = ListQuery::from_query_string("tag=x&q=a%20b&after=3&limit=5").unwrap();
        assert_eq!(
            q,
            ListQuery { tag: Some("x".into()), q: Some("a b".into()), after: Some(3), limit: 5 }
        );
        assert_eq!(ListQuery::from_query_string("").unwrap(), ListQuery::default());
        for bad in ["limit=0", "limit=101", "limit=x", "limit=", "after=x", "after=1.5"] {
            assert!(ListQuery::from_query_string(bad).is_err(), "{bad}");
        }
    }
}
